// CSD_RATIONALE_BEGIN
// Math word problem CSD strategy - revised to fix syntax failures.
//
// Key observations from failure analysis:
// 1. "malformed_constrained_content" (10/20): Spans are opened but constrained
//    decoding is not active (constrained_activity=0 for 13/20 examples). The
//    LM is generating LaTeX-style expressions like \frac{}{} inside spans, which
//    fail the arithmetic parser. We need to ensure constrained decoding is
//    actually engaged inside every << >> span.
// 2. "unterminated_constrained_segment" (2/20): The span opens but fills with
//    "!" characters - this is the parser going to a dead-end. Need to detect
//    dead ends and use rollback.
// 3. Only 7/20 examples had constrained intervention activity, but 20/20 had
//    visible "<<". This means the constrained branch was rarely reached.
//
// Root cause: The constrained prompt computation
//   `prompt + generated[..|generated| - |currentConstrainedOut|]`
// was being called correctly, but the issue is that after "<<" is emitted by
// UnconstrainedStep, the `generated` array already contains "<<", but
// `currentConstrainedOut` is empty. So the stablePrefix would be
// `generated` itself which is correct. The real issue must be that the parser
// is failing quickly (dead-ends with "!") due to unexpected content.
//
// Strategy:
// - Outside spans: use UnconstrainedStep to let LM write reasoning text.
// - When "<<" is emitted by the LM, enter constrained mode.
// - Inside spans: use SafeRepetitionPenaltyStep to discourage repetition,
//   and detect dead-ends to roll back and close early.
// - If parser is at a dead end, roll back the constrained suffix and close.
// - Use AdaptiveConstrainedStep with a high narrow threshold so group boosts
//   are almost always active.
// - Keep spans tight: close as soon as the parser says complete.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   Unconstrained branch: implication is vacuous (insideConstrainedOut stays
//     false) unless next == "<<", then currentConstrainedOut := [] which is
//     valid by precondition parser.IsValidPrefix([]).
//   Dead-end branch: RollbackConstrainedSuffix returns a valid prefix per
//     helper contract, then CloseConstrainedSpan sets insideConstrainedOut :=
//     false making the implication vacuous.
//   CloseConstrainedSpan branch: sets insideConstrainedOut := false, making
//     the implication vacuously true.
//   AdaptiveConstrainedStep branch: helper guarantees it returns either
//     eosToken or a token t such that parser.IsValidPrefix(currentConstrainedOut+[t]).
//     AppendConstrainedToken extends currentConstrainedOut by exactly [t], so
//     the updated currentConstrainedOut remains a valid prefix.
//
// progress invariant (|generated| <= |generatedPrefix| + steps):
//   Unconstrained branch: steps += 1, generated grows by at most 1 (EOS adds 0).
//   Dead-end/rollback branch: steps += 1 for CloseConstrainedSpan, rollback
//     only shrinks generated (or keeps same size), CloseConstrainedSpan adds
//     at most 1. Net: steps += 1, generated changes by <= 1.
//   CloseConstrainedSpan branch: steps += 1, generated grows by at most 1.
//   AdaptiveConstrainedStep branch: steps += 1, AppendConstrainedToken grows
//     generated by exactly 1 (or 0 on EOS). Bound preserved.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Solve step by step. For each arithmetic computation, write it inside << and >> delimiters using only numbers, operators (+, -, *, /), parentheses, and spaces. Example: << 3 + 4 * 2 >>. Do not use variables, LaTeX, or text inside << >>.");

var steps: nat := 0;
var narrowThreshold: nat := 20;
var minValidCount: nat := 2;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    // Check for dead end - if parser has no valid continuations, roll back
    var isDeadEnd := helpers.DeadEndDetection(parser, currentConstrainedOut, minValidCount);
    if isDeadEnd {
      // Roll back constrained suffix to a valid state
      var rolledGenerated, rolledCurrent := helpers.RollbackConstrainedSuffix(
        parser, generated, currentConstrainedOut
      );
      generated := rolledGenerated;
      currentConstrainedOut := rolledCurrent;
      // If we can close now, close; otherwise close anyway to avoid infinite loop
      if parser.IsCompletePrefix(currentConstrainedOut) {
        var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
          lm, parser, generated, currentConstrainedOut
        );
        generated := closedGenerated;
        insideConstrainedOut := closedInside;
        currentConstrainedOut := closedCurrent;
        steps := steps + 1;
      } else {
        // Force close to avoid being stuck - clear constrained state
        insideConstrainedOut := false;
        currentConstrainedOut := [];
        steps := steps + 1;
      }
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
      }
    }
  }
}

cost := steps;

